#include <stdio.h>
#include <stdlib.h>
#include <math.h>

void hanoi(int disco, char orig, char dest, char aux) {

    if (disco == 1)
        printf("Move disco %d de %c para %c\n", disco, orig, dest);

    else {
        hanoi(disco - 1, orig, aux, dest);
        printf("Move disco %d de %c para %c\n", disco, orig, dest);
        hanoi(disco - 1, aux, dest, orig);
    }
}
int main(void) {
    setbuf(stdout, NULL);
    printf("** Torre de Hanoi **\n");
    int n;
    char sair;
    do {
        do {
            printf("\nDigite o numero de discos: ");
            fflush(stdin);
            scanf("%d", &n);
            if (n > 10)
                printf("\nLimite de discos excedido!(10)\n");
        } while (n > 10);
        printf("\n");
        hanoi(n, 'A', 'B', 'C');
        printf("\nNumero de movimentos otimos: %.0f\n\n", pow(2, n) - 1);
        printf("Deseja sair? (s/n): ");
        fflush(stdin);
        scanf("%c", &sair);
    } while (sair == 'n');
    printf("\nVoce saiu do programa.");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct lista {
    int coef;
    int expo;
    struct lista *prox;
};

typedef struct lista TLista;
TLista *insere(int coef, int expo, TLista *lista) {

    TLista *aux;
    aux = (TLista *)malloc(sizeof(TLista));
    aux->coef = coef;
    aux->expo = expo;

    if (lista) {
        TLista *aux2 = lista;
        aux->prox = lista;
        do {
            aux2 = aux2->prox;
        } while (aux2->prox != lista);
        aux2->prox = aux;
    } else
        aux->prox = aux;

    return aux;
}

int verifica(TLista *lista) { return lista == NULL; }
void imprime(TLista *lista, TLista *aux) {
    char ch = '+';
    if (aux->coef < 0) {
        ch = ' ';
    }
    if (aux->prox == lista) {
        if (aux->expo != 0)
            printf("%c%dx^%d ", ch, aux->coef, aux->expo);
        else
            printf("%c%d", ch, aux->coef);
    } else {
        imprime(lista, aux->prox);
        if (aux->expo != 0)
            printf("%c%dx^%d ", ch, aux->coef, aux->expo);
        else
            printf("%c%d", ch, aux->coef);
    }
}

TLista *inicializa(void) { return NULL; }

TLista *ordena(TLista *lista) {
    TLista *aux;
    aux = lista;
    do {

        if (lista->expo < lista->prox->expo) {
            aux->coef = lista->prox->coef;
            aux->expo = lista->prox->expo;
            aux->prox->coef = lista->coef;
            aux->prox->expo = lista->expo;
        }
        lista = lista->prox;
        aux = aux->prox;

    } while (aux != lista);

    return aux;
}
int main(void) {

    setbuf(stdout, NULL);
    int opcao = 0, expo = 0, coef = 0;
    TLista *lista;
    lista = inicializa();

    printf("Polinémio\n");
    do {
        printf("\nMenu\n");
        printf("1-Inserir Dado\n");
        printf("2-Imprimir Polinémio\n");
        printf("3-Imprimir Polinémio Ordenado\n");
        printf("0-Sair\n");
        printf("\nOpééo: ");
        fflush(stdin);
        scanf("%d", &opcao);

        switch (opcao) {
        case 1:
            printf("\nDigite o coeficiente: ");
            fflush(stdin);
            scanf("%d", &coef);
            printf("Digite o expoente: ");
            fflush(stdin);
            scanf("%d", &expo);
            lista = insere(coef, expo, lista);
            printf("\nDado inserido com sucesso.\n");
            break;
        case 2:
            if (!verifica(lista)) {
                printf("\nPolinémio: ");
                imprime(lista, lista);
                printf("\n");
            } else
                printf("Néo existe expresséo.\n");
            break;
        case 3:
            if (!verifica(lista)) {
                printf("\nPolinémio: ");
                imprime(ordena(lista), ordena(lista));
                printf("\n");
            } else
                printf("Néo existe expresséo.\n");
            break;
        case 0:
            // Sair
            break;
        default:
            printf("Opééo invélida.");
            break;
        }
    } while (opcao != 0);
    // Fim da Aplicaééo
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

float normal(float x) {
    float fat = 1;
    while (x != 1) {
        fat = fat * x;
        x = x - 1;
    }
    return fat;
}

int main(void) {
    setbuf(stdout, NULL);
    float x;
    printf("** Fatorial Normal **\n\n");
    printf("Digite um némero: ");
    fflush(stdin);
    scanf("%f", &x);
    printf("fatorial de %.0f: %.0f", x, normal(x));

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int fat(int n) {
    if (n)
        return n * fat(n - 1);
    else
        return 1;
}

int main() {
    setbuf(stdout, NULL);
    int n;
    printf("** Fatorial **\n\n");
    printf("Digite um valor para n: ");
    scanf("%d", &n);
    printf("\nO fatorial de %d e %d", n, fat(n));

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int fib(int n) {
    if (n == 0)
        return (0);
    else if (n == 1)
        return (1);
    else
        return (fib(n - 1) + fib(n - 2));
}

int main(void) {
    setbuf(stdout, NULL);
    int x;
    printf("** Fibonacci **\n\n");
    printf("Digite um némero: ");
    fflush(stdin);
    scanf("%d", &x);
    printf("\nFibonacci de %d é %d", x, fib(x));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct lista TLista;
struct lista {
    int dado;
    TLista *prox;
};
TLista *aux2;
TLista *inicializa() { return NULL; }
TLista *insere(int num, TLista *lista) {
    TLista *aux;
    aux = (TLista *)malloc(sizeof(TLista));
    aux->dado = num;
    if (!lista) {
        aux->prox = aux;
    } else {
        TLista *cont = lista->prox;
        do {
            cont = cont->prox;
        } while (cont->dado != lista->prox->dado);
        aux->prox = cont;
        lista->prox = aux;
    }
    return aux;
}
void imprime(TLista *lista, TLista *cont) {
    do {
        printf("%d", cont->dado);
        cont = cont->prox;
    } while (cont != lista);
}
int localiza(TLista *lista, int j) {
    int i;
    for (i = 1; i <= j; i++) {
        lista = lista->prox;
    }
    return lista->dado;
}
TLista *remover(TLista *lista, int j) {
    int i;
    TLista *aux;
    j--;
    for (i = 1; i <= j; i++) {
        lista = lista->prox;
    }
    aux = lista->prox->prox;
    free(lista->prox);
    lista->prox = aux;
    return lista;
}
int existe(TLista *lista) { return (lista->prox == lista) ? 0 : 1; }
int verifica(TLista *lista) { return lista == NULL; }
int main(void) {
    setbuf(stdout, NULL);
    TLista *lista;
    lista = inicializa();
    int opcao = 0, i, cont = 0, j = 0;
    printf("JOSEPHUS\n");
    do {
        printf("\nMenu\n");
        printf("1-Némero de Componentes\n");
        printf("2-Intervalo de Eliminação\n");
        printf("3-Ordem de Eliminação e Sobrevivente\n");
        printf("0-Sair\n");
        printf("\nOpção: ");
        fflush(stdin);
        scanf("%d", &opcao);
        switch (opcao) {
        case 1:
            printf("\nDigite o número de componentes: ");
            fflush(stdin);
            scanf("%d", &cont);
            for (i = 1; i <= cont; i++) {
                lista = insere(i, lista);
            }
            break;
        case 2:
            if (!verifica(lista)) {
                printf("\nDigite o intervalo de eliminaééo: ");
                fflush(stdin);
                scanf("%d", &j);
            } else
                printf("Néo existem componentes.\n");
            break;
        case 3:
            if (!verifica(lista)) {
                if (j != 0) {
                    printf("Ordem de Eliminação: ");
                    while (existe(lista)) {
                        printf("%d ", localiza(lista, j));
                        lista = remover(lista, j);
                    }
                    printf("\nSobrevivente: ");
                    imprime(lista, lista);
                    printf("\n");
                } else
                    printf("\nInforme o intervalo de eliminaçõo.\n");
            } else
                printf("Néo existem componentes.\n");
            break;
        case 0:
            // Sair
            break;
        default:
            printf("Opção inválida.\n");
            break;
        }
    } while (opcao != 0);
    // Fim da Aplicação
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

void StrCpy(char *dest, char *orig) {
    while (*orig) {
        *dest = *orig;
        dest++;
        orig++;
    }
    *dest = '\0';
}

void StrCat(char *str1, char *str2) {
    while (*str1)
        str1++;
    StrCpy(str1, str2);
}

int StrLen(char *orig) {
    int cont = 0;
    while (*orig++)
        cont++;
    return cont;
}

// Funcao para verificar tamanho da String - Recursiva
int tamStr(char *str, int cont) { return (*str++) ? cont++, tamStr(str, cont) : --cont; }

// Funcao para imprimir caracteres da String
void imprimeStr(char str) { printf("%c", str); }

// Funcao para inverter String - Recursiva
void inverteStr(char *str, int i) {
    (i) ? imprimeStr(str[i]), inverteStr(str, --i) : imprimeStr(str[i]);
}

int main() {
    setbuf(stdout, NULL);
    char ch[20] = "face", ch2[20];
    printf("Entre com uma palavra: ");
    fflush(stdin);
    gets(ch2);
    StrCpy(ch, ch2);
    printf("%s\n", ch);
    StrCat(ch, ch2);
    printf("%s\n", ch);
    printf("%d", StrLen(ch));
    printf("** Inverte String **\n\n");
    char str[100];
    printf("Digite a String: ");
    fflush(stdin);
    gets(str);
    printf("String invertida: ");
    inverteStr(str, tamStr(str, 0));

    return 0;
}

