void mult(float *ptr, float *ptr2, float *z) { *z = (*ptr * *ptr2); }
void sub(float *ptr, float *ptr2, float *z) { *z = (*ptr - *ptr2); }
void adi(float *ptr, float *ptr2, float *z) { *z = (*ptr + *ptr2); }
