                //Registra jogada para jogador 2
                registrajogada(2);
                //Verifica se jogador 2 eh o vencedor
                if (verificavencedor(2) == 0) {
                    //Verifica se deu empate
                    inf = verificaempate();
                } else
                    inf = 0;
            }
        }
    }
    return 0;
}
